contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable {
        require(caller != address(0), "zero caller");
        uint256 preBalance = address(c).balance;

        // drive the public entry withdraw through the test contract, which is the owner
        bool withdrawReverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        uint256 postBalance = address(c).balance;

        assert(
            (withdrawReverted && postBalance == preBalance) ||
            (!withdrawReverted && postBalance == 0)
        );
    }

    receive() external payable {}
}

