// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(address caller) internal {
        vm.assume(caller != address(0));
        uint256 preBalance = address(c).balance;
        bool withdrawReverted;
        try c.withdraw() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 postBalance = address(c).balance;
        assertTrue((withdrawReverted && postBalance == preBalance) ||
            (!withdrawReverted && postBalance == 0));
    }

    function testFuzz_run(address caller) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller);
    }

    receive() external payable {}
}
